"use client";

import { use, useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { LucideIcon } from "lucide-react";
import { AlertTriangle, ArrowLeft, ArrowRight, BadgeAlert, BookOpenCheck, Boxes, Braces, CheckCircle2, ChevronDown, CircleDashed, CircleX, Clock3, Crosshair, Download, ExternalLink, Eye, EyeOff, FileJson, FileSearch, Fingerprint, Gauge, GitBranch, IdCard, KeyRound, LayoutDashboard, ListChecks, LockKeyhole, Network, PencilLine, RadioTower, RotateCw, ScanSearch, ShieldAlert, ShieldCheck, Sparkles, Unplug, Upload, Users, Wrench } from "lucide-react";
import { toast } from "sonner";
import { api, artifactURL } from "@/lib/api";
import type { Assessment, Finding, SchemaSignal, ToolProfile } from "@/lib/types";
import { AssessmentStatusBadge, Card, InfoTip, PageHeading, Score, StatusBadge } from "@/components/page";

const tabs=[
  {id:"overview",label:"Overview",icon:LayoutDashboard,description:"What the assessment established, where uncertainty remains, and what AgntID could change."},
  {id:"findings",label:"Findings",icon:ListChecks,description:"Prioritized issues, why each matched, all affected tools, and the recommended response."},
  {id:"tools",label:"Tools",icon:Boxes,description:"Search each advertised capability and review its impact, contract, evidence strength, and policy outcome."},
  {id:"governance",label:"Governance",icon:ScanSearch,description:"Catalog changes, agent-facing content, metadata warning patterns, and recurring contract gaps."},
  {id:"policy",label:"Policy",icon:ShieldCheck,description:"What identities can see, what was not tested, and how illustrative AgntID controls could reduce exposure."},
  {id:"evidence",label:"Evidence",icon:FileSearch,description:"The technical audit trail, clearly separated into measured, sampled, inferred, and unavailable evidence."},
  {id:"timeline",label:"Timeline",icon:Clock3,description:"Which assessment stages completed, which were not assessed, and how long each took."},
  {id:"artifacts",label:"Reports",icon:Download,description:"Downloadable executive, technical, machine-readable, and audit artifacts."},
];
export default function AssessmentDetail({params}:{params:Promise<{id:string}>}){const {id}=use(params);const router=useRouter();const [assessment,setAssessment]=useState<Assessment|null>(null);const [error,setError]=useState("");const [tab,setTab]=useState("overview");const [focusTool,setFocusTool]=useState("");const [focusFinding,setFocusFinding]=useState("");const [rerunning,setRerunning]=useState(false);useEffect(()=>{let stopped=false;const load=()=>api.assessment(id).then(a=>{if(!stopped)setAssessment(a);if(!["completed","partial","failed","canceled"].includes(a.status))setTimeout(load,900)}).catch(e=>setError(e.message));load();return()=>{stopped=true}},[id]);if(error)return <div className="notice danger-notice" role="alert"><AlertTriangle size={16}/>{error}</div>;if(!assessment)return <div className="card assessment-status-loading" role="status" aria-live="polite" aria-busy="true"><span className="skeleton" aria-hidden="true"/><div><strong>Loading assessment status</strong><p>Retrieving the latest report progress.</p></div></div>;const openTool=(name:string)=>{setFocusTool(name);setTab("tools")};const openFinding=(findingId:string)=>{setFocusFinding(findingId);setTab("findings")};const editHref=`/assessments/new?mode=${assessment.mode==="offline"?"offline":"live"}&target=${encodeURIComponent(assessment.target.url)}`;const authentication=assessment.server.authentication?.toLowerCase()||"";const needsSignIn=assessment.oauth.protected||assessment.connectionStatus==="authentication-required"||["required","oauth","bearer","token","api-key"].some(value=>authentication.includes(value));const scanAgain=async()=>{if(assessment.mode==="live"&&needsSignIn){router.push(`${editHref}&signin=required`);return}setRerunning(true);try{const result=await api.create({mode:assessment.mode==="sample"?"sample":"live",target:{protocol:"mcp",url:assessment.target.url}});toast.success("New assessment started");router.push(`/assessments/${result.assessmentId}`)}catch(cause){toast.error(cause instanceof Error?cause.message:"Unable to start a new assessment");setRerunning(false)}};const inProgress=["queued","running"].includes(assessment.status);return <>
  <PageHeading eyebrow={inProgress?"Assessment in progress":assessmentSourceLabel(assessment.mode)} title={inProgress?"Preparing your MCP readiness report":assessment.target.host||assessment.target.url} description={inProgress?(assessment.target.host||assessment.target.url):assessment.target.url} actions={inProgress?<><AssessmentStatusBadge status={assessment.status} connectionStatus={assessment.connectionStatus}/><Link href="/assessments" className="button"><ArrowLeft size={13}/>History</Link></>:<><AssessmentStatusBadge status={assessment.status} connectionStatus={assessment.connectionStatus}/>{assessment.mode==="live"&&<Link href={editHref} className="button primary"><PencilLine size={13}/>Edit assessment</Link>}{assessment.mode==="offline"&&<Link href={editHref} className="button primary"><Upload size={13}/>Upload updated data</Link>}{assessment.mode!=="offline"&&<button type="button" className="button" disabled={rerunning} onClick={()=>void scanAgain()}><RotateCw size={13} className={rerunning?"animate-spin":undefined}/>{rerunning?"Starting…":"Assess again"}</button>}<Link href="/assessments" className="button"><ArrowLeft size={13}/>History</Link></>}/>
  {inProgress?<AssessmentProgress a={assessment}/>:<>
    <ConnectionOutcome a={assessment} onTimeline={()=>setTab("timeline")}/>
    <div className="tabs" role="tablist" aria-label="Assessment sections">{tabs.map(item=>{const Icon=item.icon;return <button key={item.id} type="button" role="tab" aria-selected={tab===item.id} title={item.label} className={`tab ${tab===item.id?"active":""}`} onClick={()=>setTab(item.id)}><Icon size={14}/><span>{item.label}</span></button>})}</div>
    <TabContext tab={tab}/>
    {tab==="overview"&&<Overview a={assessment}/>}
    {tab==="findings"&&<Findings a={assessment} focusFinding={focusFinding} onOpenTool={openTool}/>}
    {tab==="tools"&&<Tools a={assessment} focusTool={focusTool} onOpenFinding={openFinding}/>}
    {tab==="governance"&&<IntegrityDrift a={assessment}/>}
    {tab==="policy"&&<IdentityPolicy a={assessment}/>}
    {tab==="evidence"&&<Evidence a={assessment}/>}
    {tab==="timeline"&&<Timeline a={assessment}/>}
    {tab==="artifacts"&&<Artifacts a={assessment}/>}
  </>}
  </>}

function TabContext({tab}:{tab:string}){const item=tabs.find(candidate=>candidate.id===tab)||tabs[0];const Icon=item.icon;return <div className="tab-context"><span><Icon size={15}/></span><div><strong>{item.label}</strong><p>{item.description}</p></div></div>}
function assessmentSourceLabel(mode:string){return ({live:"Live metadata assessment",offline:"Uploaded metadata assessment",sample:"Guided example"} as Record<string,string>)[mode]||"Assessment"}

type ProgressPhase={id:string;title:string;description:string;runIds:string[];icon:LucideIcon};
const progressPhases:ProgressPhase[]=[
  {id:"connect",title:"Connecting",description:"Establishing a standards-based MCP session and validating endpoint reachability.",runIds:["queue","discovery","transport"],icon:Network},
  {id:"authentication",title:"Analyzing Authentication",description:"Reviewing access challenges and OAuth metadata, including scopes, PKCE, and registration support.",runIds:["authentication","oauth-posture"],icon:KeyRound},
  {id:"identity",title:"Evaluating Identity Exposure",description:"Comparing catalog visibility for anonymous and configured identities in isolated sessions.",runIds:["authorization"],icon:Users},
  {id:"catalog",title:"Discovering Catalog",description:"Structuring the advertised tools, prompts, resources, and protocol capabilities that define the assessment scope.",runIds:["protocol","tool-discovery"],icon:Boxes},
  {id:"metadata",title:"Inspecting Tool Metadata",description:"Evaluating descriptions, annotations, schemas, declared effects, and metadata integrity—without invoking capabilities.",runIds:["tool-classification","content-integrity","contract-readiness","ai-readiness"],icon:Braces},
  {id:"policy",title:"Assessing Policy Readiness",description:"Checking operational signals, catalog changes, rules, and where explicit runtime controls could improve readiness.",runIds:["operational","catalog-drift","rule-evaluation"],icon:ShieldCheck},
  {id:"summary",title:"Generating Executive Summary",description:"Turning observed evidence into readiness scores, findings, recommendations, and downloadable report formats.",runIds:["report-generation"],icon:FileJson},
];
function phaseState(a:Assessment,phase:ProgressPhase){const runs=phase.runIds.map(id=>a.engineRuns.find(run=>run.id===id)).filter(Boolean) as Assessment["engineRuns"];if(phase.runIds.includes(a.currentStage||"")||runs.some(run=>run.status==="running"))return "current";if(runs.length>0&&runs.every(run=>["completed","partial","failed","not-assessed"].includes(run.status)))return "complete";return "upcoming"}
function AssessmentProgress({a}:{a:Assessment}){const phases=progressPhases.map(phase=>({...phase,state:phaseState(a,phase)}));const active=phases.find(phase=>phase.state==="current")||phases.find(phase=>phase.state==="upcoming")||phases[phases.length-1];return <div className="assessment-progress-page" aria-live="polite" aria-busy="true">
  <section className="card progress-overview" aria-labelledby="progress-title"><div className="progress-overview-copy"><div className="progress-live"><span/>Report preparation in progress</div><h2 id="progress-title">{active.title}</h2><p>{active.description}</p></div><div className="progress-percentage"><strong>{Math.max(0,Math.min(100,a.progress))}%</strong><span>complete</span></div><div className="progress progress-track" role="progressbar" aria-label="Assessment progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.max(0,Math.min(100,a.progress))}><span style={{width:`${Math.max(0,Math.min(100,a.progress))}%`}}/></div><p className="progress-leave-note">This assessment continues safely in the background. You can leave this page and return from Assessment History.</p></section>
  <div className="progress-layout"><section className="card phase-card" aria-labelledby="phases-title"><div className="phase-card-heading"><div><div className="section-label">Report workflow</div><h2 id="phases-title">What the assessment is doing</h2><p>Each phase evaluates observable MCP posture and contributes evidence to the final report.</p></div><span>{phases.filter(phase=>phase.state==="complete").length} of {phases.length} phases complete</span></div><div className="assessment-phases">{phases.map((phase,index)=>{const Icon=phase.icon;return <div className={`assessment-phase ${phase.state}`} key={phase.id}><div className="phase-rail"><span className="phase-icon">{phase.state==="complete"?<CheckCircle2 size={16}/>:<Icon size={16}/>}</span>{index<phases.length-1&&<i/>}</div><div className="phase-copy"><div><strong>{phase.title}</strong><span>{phase.state==="current"?"In progress":phase.state==="complete"?"Complete":"Waiting"}</span></div><p>{phase.description}</p></div></div>})}</div></section>
  <aside className="card progress-safety" aria-labelledby="safety-progress-title"><div className="progress-safety-heading"><span><ShieldCheck size={19}/></span><div><div className="section-label">Safe throughout</div><h2 id="safety-progress-title">Observation without execution</h2></div></div><p>The assessment reads declared MCP information only. Its safety boundaries do not change between phases.</p><div className="progress-assurances"><div><CheckCircle2 size={15}/><span><strong>No MCP tools are executed</strong>Discovered capabilities are classified from their contracts and metadata.</span></div><div><CheckCircle2 size={15}/><span><strong>No prompts are sent</strong>Prompt metadata may be inventoried, but prompts are never invoked or submitted to a model.</span></div><div><CheckCircle2 size={15}/><span><strong>No payload fuzzing occurs</strong>Published schemas are inspected as declared; no synthetic attack payloads are sent.</span></div></div><div className="progress-safety-footer"><LockKeyhole size={14}/>Configured identities remain isolated during metadata discovery.</div></aside></div>
</div>}

function ConnectionOutcome({a,onTimeline}:{a:Assessment;onTimeline:()=>void}){const authenticationRequired=a.connectionStatus==="authentication-required";const connectionFailed=a.connectionStatus==="connection-failed";if(!authenticationRequired&&!connectionFailed&&!(a.connectionStatus==="connected"&&a.status==="partial"))return null;if(a.connectionStatus==="connected")return <div className="connection-outcome partial-outcome"><CircleDashed size={19}/><div><strong>MCP connected; some assessment checks were incomplete</strong><p>The discovered catalog is available, but one or more later stages reported a partial result.</p></div><button className="button" onClick={onTimeline}>View incomplete stages</button></div>;const authentication=a.server.authentication?.toLowerCase()||"";const signInNeeded=authenticationRequired||a.oauth.protected||["required","oauth","bearer","token","api-key"].some(value=>authentication.includes(value));const retryHref=`/assessments/new?mode=live&target=${encodeURIComponent(a.target.url)}${signInNeeded?"&signin=required":""}`;return <div className={`connection-outcome ${authenticationRequired?"authentication-outcome":"failed-outcome"}`}>{authenticationRequired?<KeyRound size={19}/>:<CircleX size={19}/>}<div><strong>{authenticationRequired?"Authentication required — MCP did not connect":"MCP connection failed"}</strong><p>{authenticationRequired?"The endpoint responded, but none of the configured identities established an MCP session. No tool catalog was discovered. Sign in or supply the required token, then start a new assessment.":"No configured identity established an MCP session. Tool, protocol, and AI-readiness results were not assessed."}</p></div><Link className="button primary" href={retryHref}>Edit assessment</Link></div>}

function Overview({a}:{a:Assessment}){
  const dims=Object.values(a.scorecard?.dimensions||{});
  if(["authentication-required","connection-failed"].includes(a.connectionStatus))return <div className="grid two-column"><Card title="Assessment outcome"><div className="unassessed-summary"><span className="unassessed-icon"><Unplug size={22}/></span><div><h2>No MCP catalog was assessed</h2><p className="subtitle">{a.executiveSummary||"An MCP session was not established, so readiness is not scored."}</p></div></div></Card><Card title="What Observatory confirmed"><ProfileRow icon={<Network size={14}/>} label="Endpoint response" value={a.connectionStatus==="authentication-required"?"Authentication challenge observed":"Connection unavailable"}/><ProfileRow icon={<ShieldCheck size={14}/>} label="Authentication" value={a.server.authentication||"Not established"}/><ProfileRow icon={<Wrench size={14}/>} label="Tools discovered" value="Not assessed"/><ProfileRow icon={<Gauge size={14}/>} label="Readiness score" value="Not assessed"/></Card></div>;
  const readOnly=a.policySimulation.profiles.find(profile=>profile.id==="read-only");
  const reducedTokens=readOnly?estimatedProfileTokens(a,readOnly.visibleToolNames):0;
  const reduction=a.context.totalTokens>0&&reducedTokens>0?Math.round((1-reducedTokens/a.context.totalTokens)*100):0;
  const comparisonReady=a.identityExposure.comparedProfiles>=2;
  return <div className="grid">
    <div className="grid two-column"><Card><div style={{padding:24,display:"flex",gap:30,alignItems:"center",flexWrap:"wrap"}}><Score value={a.scorecard?.overall||0}/><div style={{flex:1,minWidth:240}}><div className="eyebrow">Executive summary</div><h2 style={{fontSize:20,marginBottom:9}}>Readiness with {Math.round(a.scorecard?.coverage||0)}% coverage</h2><p className="subtitle" style={{lineHeight:1.7}}>{a.executiveSummary||"The assessment is collecting evidence and preparing its scorecard."}</p><p className="score-boundary">The score combines measured checks with confidence-adjusted metadata inferences. No MCP tool was executed.</p></div></div><div className="grid metrics-grid" style={{padding:"0 24px 24px"}}>{dims.map(d=><div key={d.name} style={{padding:14,border:"1px solid var(--border)",borderRadius:10}}><div className="metric-label">{d.name}</div><div style={{fontSize:22,fontWeight:750,margin:"7px 0"}}>{d.score}</div><div className="mini-progress" style={{width:"100%"}}><span style={{width:`${d.score}%`}}/></div><div className="field-help">{Math.round(d.coverage)}% coverage · {d.status.replaceAll("-"," ")}</div></div>)}</div></Card><div className="grid"><Card title="What this assessment established"><ProfileRow icon={<Network size={14}/>} label="Connection" value="MCP catalog connected"/><ProfileRow icon={<Wrench size={14}/>} label="Catalog visibility" value={`${a.tools.length} tools advertised`}/><ProfileRow icon={<Users size={14}/>} label="Identity comparison" value={comparisonReady?`${a.identityExposure.comparedProfiles} connected profiles compared`:"Needs 2 connected profiles"}/><ProfileRow icon={<ShieldCheck size={14}/>} label="Tool execution" value="Not tested"/></Card><Card title="Findings by severity"><div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>{Object.entries(a.risk).map(([name,value])=><div key={name} style={{textAlign:"center",padding:10,border:"1px solid var(--border)",borderRadius:9}}><strong style={{display:"block",fontSize:20}}>{value}</strong><StatusBadge value={name}/></div>)}</div></Card></div></div>
    {readOnly&&<Card title="What AgntID could change" description="Illustrative policy outcome derived from this catalog; no runtime AgntID policy was applied."><div className="outcome-comparison"><div><span>Current catalog</span><strong>{a.tools.length} tools</strong><small>{a.context.totalTokens.toLocaleString()} estimated tokens</small></div><ArrowRight size={20}/><div><span>AgntID Read Only</span><strong>{readOnly.visibleCount} tools</strong><small>{reducedTokens.toLocaleString()} estimated tokens</small></div><div className="outcome-benefit"><b>{readOnly.hiddenCount}</b><span>change-capable tools hidden</span></div>{reduction>0&&<div className="outcome-benefit"><b>{reduction}%</b><span>less initialization context</span></div>}</div></Card>}
  </div>
}
function estimatedProfileTokens(a:Assessment,visibleToolNames:string[]){const names=new Set(visibleToolNames);const toolTokens=a.tools.filter(tool=>names.has(tool.name)).reduce((sum,tool)=>sum+(tool.estimatedTokens||0),0);return toolTokens+a.context.promptTokens+a.context.resourceTokens+a.context.instructionTokens}
function ProfileRow({icon,label,value}:{icon:React.ReactNode;label:string;value:string}){return <div style={{display:"flex",alignItems:"center",gap:10,padding:"11px 0",borderBottom:"1px solid var(--border)"}}><span style={{color:"var(--primary)"}}>{icon}</span><span style={{color:"var(--muted)",fontSize:11,flex:1}}>{label}</span><strong style={{fontSize:11,textTransform:"capitalize"}}>{value}</strong></div>}
const displayedFindingToolLimit=12;
function findingTools(finding:Finding){return finding.toolNames?.length?finding.toolNames:finding.replay?.toolNames||[]}
function displayedFindingTools(finding:Finding){return findingTools(finding).slice(0,displayedFindingToolLimit)}
function findingAnchor(id:string){return `finding-${encodeURIComponent(id)}`}
function findingScope(finding:Finding){const tools=findingTools(finding);if(tools.length)return {label:`${tools.length} affected ${tools.length===1?"tool":"tools"}`,detail:"This finding is explicitly linked to the tools below."};if(finding.classification==="posture")return {label:"Server",detail:"This finding applies to server or transport posture, not to one tool."};if(finding.classification==="integrity")return {label:"Metadata",detail:"This finding applies to advertised metadata and may involve server instructions, prompts, resources, schemas, or tools."};return {label:"Catalog",detail:"This is a catalog-wide observation; no individual tool was identified by the assessment evidence."}}
function Findings({a,focusFinding,onOpenTool}:{a:Assessment;focusFinding:string;onOpenTool:(name:string)=>void}){useEffect(()=>{if(!focusFinding)return;const frame=requestAnimationFrame(()=>document.getElementById(findingAnchor(focusFinding))?.scrollIntoView({behavior:"smooth",block:"center"}));return()=>cancelAnimationFrame(frame)},[focusFinding]);const [classification,setClassification]=useState("all");const classes=["all",...Array.from(new Set(a.findings.map(f=>f.classification)))];const visible=classification==="all"?a.findings:a.findings.filter(f=>f.classification===classification);return <Card title={`${a.findings.length} findings`} description="Review issues by severity and scope, then expand any finding to understand the rule, evidence, and recommended response." action={<InfoTip text="Severity affects risk priority. Scope shows whether evidence applies to the server, catalog, metadata, or specific tools."/>}><div className="finding-filter"><div className="severity-glance"><span className="high"><ShieldAlert size={13}/><b>{a.risk.critical+a.risk.high}</b> priority</span><span className="medium"><AlertTriangle size={13}/><b>{a.risk.medium}</b> review</span><span className="info"><Gauge size={13}/><b>{a.risk.info+a.risk.low}</b> advisory</span></div><span>{visible.length} shown</span><select className="select" aria-label="Filter findings by rule class" value={classification} onChange={e=>setClassification(e.target.value)}>{classes.map(value=><option value={value} key={value}>{value==="all"?"All rule classes":value.replaceAll("-"," ")}</option>)}</select></div>{a.findings.length===0?<div className="empty"><ShieldCheck size={28}/>No actionable findings have been produced.</div>:visible.length===0?<div className="empty"><ShieldCheck size={28}/>No findings match this rule class.</div>:<div className="finding-list">{visible.map(f=><details id={findingAnchor(f.id)} className={`finding-row ${focusFinding===f.id?"focused-finding":""}`} open={focusFinding===f.id||undefined} key={f.id}><summary><FindingGlyph classification={f.classification}/><div className="finding-headline"><h3>{f.title}</h3><p>{f.description}</p><span>{f.ruleId}</span></div><div className="finding-tags"><StatusBadge value={f.severity}/><span className="badge">{f.classification}</span><span className="entity-scope"><Wrench size={11}/>{findingScope(f).label}</span></div><div className="penalty">{f.penalty>0?`−${f.penalty}`:"Advisory"}<ChevronDown size={14}/></div></summary><div className="finding-body"><FindingRuleContext finding={f} assessment={a}/><div className="finding-explain"><section><CircleHelpIcon/><div><strong>Why it matters</strong><p>{f.whyItMatters}</p></div></section><section><ShieldCheck size={16}/><div><strong>Recommended action</strong><p>{f.recommendation.detail}</p></div></section></div>{findingTools(f).length>0?<div className="finding-tools"><span>Affected tools · {findingTools(f).length} total</span>{displayedFindingTools(f).map(name=><button type="button" className="tool-link" key={name} onClick={()=>onOpenTool(name)}><Wrench size={12}/>{name}</button>)}{findingTools(f).length>displayedFindingToolLimit&&<small>Showing {displayedFindingToolLimit} examples · {findingTools(f).length-displayedFindingToolLimit} more linked tools</small>}</div>:<div className="finding-scope-note"><Network size={14}/><span><strong>{findingScope(f).label} scope</strong>{findingScope(f).detail}</span></div>}{f.replay&&<details className="policy-replay"><summary><GitBranch size={14}/>View illustrative policy replay</summary><div className="replay-observed"><span>Observed in this assessment</span><strong>{f.replay.observed}</strong>{f.replay.toolNames.length>0&&<div>{f.replay.toolNames.slice(0,4).map(name=><span className="badge" key={name}>{name}</span>)}{f.replay.toolNames.length>4&&<span className="badge">+{f.replay.toolNames.length-4} more</span>}</div>}</div><div className="replay-flow"><ReplayStep number="1" title="Plausible trigger" text={f.replay.trigger}/><ReplayStep number="2" title="Without explicit policy" text={f.replay.unprotectedPath}/><ReplayStep number="3" title="AgntID decision" text={f.replay.agntidDecision}/><ReplayStep number="4" title="Protected outcome" text={f.replay.protectedOutcome} protected/></div><p className="field-help">{f.replay.disclaimer}</p></details>}</div></details>)}</div>}</Card>}
function FindingRuleContext({finding,assessment}:{finding:Finding;assessment:Assessment}){const evidence=assessment.evidence.filter(item=>finding.evidenceIds.includes(item.id));const scope=findingScope(finding);return <section className="finding-rule-context"><div className="finding-rule-heading"><span className="finding-rule-icon"><BookOpenCheck size={15}/></span><div><span>Rule definition</span><strong>{finding.ruleId}</strong></div><div className="finding-rule-meta"><span>{finding.category}</span><span>{finding.dimension.replaceAll("-"," ")}</span><span>{confidenceLabel(finding.confidence)} evidence · {Math.round(finding.confidence*100)}%</span></div></div><div className="finding-rule-grid"><section><strong>What this rule checks</strong><p>{finding.description}</p></section><section><strong>Why it matched this assessment</strong><p>{findingMatchSummary(finding,evidence.length)}</p><small>{scope.detail}</small></section></div>{evidence.length>0&&<div className="finding-evidence"><span>Evidence used</span>{evidence.map(item=><div key={item.id}><FileSearch size={13}/><span><strong>{item.title}</strong><small>{item.summary}</small></span><StatusBadge value={item.observation.provenance}/></div>)}</div>}{finding.references&&finding.references.length>0&&<div className="finding-references"><span>References</span>{finding.references.map(reference=><a href={reference} target="_blank" rel="noreferrer" key={reference}>{new URL(reference).hostname}<ExternalLink size={11}/></a>)}</div>}</section>}
function confidenceLabel(value:number){if(value>=.85)return "Strong";if(value>=.7)return "Moderate";if(value>=.55)return "Limited";return "Low"}
function findingMatchSummary(finding:Finding,evidenceCount:number){const toolCount=findingTools(finding).length;if(evidenceCount>0&&toolCount>0)return `The assessment produced ${evidenceCount} supporting evidence ${evidenceCount===1?"record":"records"}, and the rule identified ${toolCount} affected ${toolCount===1?"tool":"tools"}.`;if(evidenceCount>0)return `The assessment produced ${evidenceCount} supporting evidence ${evidenceCount===1?"record":"records"} for ${findingScope(finding).label.toLowerCase()} scope.`;if(toolCount>0)return `The rule condition matched and identified ${toolCount} affected ${toolCount===1?"tool":"tools"}.`;return `The assessment evidence met this rule's condition at ${findingScope(finding).label.toLowerCase()} scope.`}
function CircleHelpIcon(){return <BadgeAlert size={16}/>}
function FindingGlyph({classification}:{classification:string}){const icons:Record<string,LucideIcon>={readiness:Gauge,"capability-chain":GitBranch,integrity:ShieldAlert,"credential-boundary":KeyRound,governance:Fingerprint,"input-boundary":Crosshair,"output-boundary":RadioTower,"policy-opportunity":LockKeyhole,posture:Network,exposure:Eye};const Icon=icons[classification]||ListChecks;return <span className={`finding-glyph ${classification}`}><Icon size={16}/></span>}
function ReplayStep({number,title,text,protected:protectedStep=false}:{number:string;title:string;text:string;protected?:boolean}){return <div className={`replay-step ${protectedStep?"protected":""}`}><span>{number}</span><div><strong>{title}</strong><p>{text}</p></div></div>}
function toolAnchor(name:string){return `tool-${encodeURIComponent(name)}`}
function findingsForTool(a:Assessment,toolName:string){return a.findings.filter(finding=>findingTools(finding).includes(toolName))}
function ToolFindings({findings,onOpenFinding}:{findings:Finding[];onOpenFinding:(findingId:string)=>void}){if(findings.length===0)return <div className="tool-findings-empty"><ShieldCheck size={14}/><span><strong>No rule findings explicitly linked</strong>This tool can still have contract observations shown below.</span></div>;return <section className="tool-findings"><div className="tool-findings-heading"><div><h3>Related findings</h3><p>Rule-backed issues explicitly linked to this tool.</p></div><span>{findings.length} {findings.length===1?"finding":"findings"}</span></div><div className="tool-finding-list">{findings.map(finding=><details className="tool-finding-item" key={finding.id}><summary><StatusBadge value={finding.severity}/><div><strong>{finding.title}</strong><span>{finding.ruleId} · {finding.classification.replaceAll("-"," ")}</span></div><ChevronDown size={14}/></summary><div className="tool-finding-body"><p>{finding.description}</p><div><section><strong>Why it matters</strong><p>{finding.whyItMatters}</p></section><section><strong>Recommended action</strong><p>{finding.recommendation.detail}</p></section></div><button type="button" className="button" onClick={()=>onOpenFinding(finding.id)}>Open in Findings <ArrowRight size={13}/></button></div></details>)}</div></section>}
function Tools({a,focusTool,onOpenFinding}:{a:Assessment;focusTool:string;onOpenFinding:(findingId:string)=>void}){useEffect(()=>{if(!focusTool)return;const frame=requestAnimationFrame(()=>document.getElementById(toolAnchor(focusTool))?.scrollIntoView({behavior:"smooth",block:"center"}));return()=>cancelAnimationFrame(frame)},[focusTool]);const [query,setQuery]=useState("");const [capability,setCapability]=useState("all");const destructive=a.tools.filter(t=>t.classification.isMutating||t.classification.effects.includes("DESTRUCTIVE")).length;const loose=a.tools.filter(t=>t.schema.signals.length).length;const conflicts=a.tools.filter(t=>t.classification.annotationContradictions.length).length;const inputSinks=a.tools.reduce((sum,t)=>sum+t.schema.inputRisks.filter(r=>r.kind!=="CREDENTIAL"&&!r.constrained).length,0);const outputBoundaries=a.tools.filter(t=>!t.schema.hasOutputSchema&&((t.annotations.openWorldHint??false)||(t.classification.isDiscover&&t.classification.executionSurface==="REMOTE_API")||t.classification.effects.includes("EXTERNAL_SERVICE_CALL")||t.classification.executionSurface==="BROWSER_SESSION")).length;const normalizedQuery=query.trim().toLowerCase();const visibleTools=a.tools.filter(tool=>(!normalizedQuery||`${tool.name} ${tool.description||""}`.toLowerCase().includes(normalizedQuery))&&(capability==="all"||(capability==="changes"?tool.classification.isMutating:!tool.classification.isMutating)));return <div className="grid">
  <div className="grid metrics-grid"><Metric label="Discovered tools" value={a.tools.length} icon={Boxes}/><Metric label="Can change data" value={destructive} icon={ShieldAlert} hint="Tools inferred to create, update, execute, or delete data. This is based on advertised metadata, not an executed call."/><Metric label="Tools with contract gaps" value={loose} icon={Braces} hint="Tools with declaration-quality observations. These are review cues, not proof that a tool is unsafe."/><Metric label="Annotation disagreements" value={conflicts} icon={BadgeAlert}/><Metric label="Unconstrained sensitive inputs" value={inputSinks} icon={Crosshair} hint="URL, path, command, script, or query inputs without a declared constraint."/><Metric label="Remote results without a schema" value={outputBoundaries} icon={RadioTower} hint="Remote or open-world read tools without an advertised output schema."/></div>
  <div className="grid two-column"><Card title="Tool intelligence" description="Search the catalog, then open a tool for its plain-language impact, linked findings, contract, and illustrative policy outcome."><div className="tool-toolbar"><input className="input" aria-label="Search tools" placeholder="Search tools by name or purpose" value={query} onChange={event=>setQuery(event.target.value)}/><select className="select" aria-label="Filter tools by capability" value={capability} onChange={event=>setCapability(event.target.value)}><option value="all">All capabilities</option><option value="changes">Can change data</option><option value="reads">Read or discover only</option></select><span>{visibleTools.length} of {a.tools.length}</span></div>{a.tools.length===0?<div className="empty"><Boxes size={26}/>No tool metadata was available.</div>:visibleTools.length===0?<div className="empty"><FileSearch size={26}/>No tools match this search.</div>:<div className="tool-list">{visibleTools.map(t=><details id={toolAnchor(t.name)} className={`tool-detail ${focusTool===t.name?"focused-tool":""}`} open={focusTool===t.name||undefined} key={t.name}><summary><div className="tool-summary"><div><strong>{t.name}</strong><span>{t.description||"No description"}</span></div><div>{findingsForTool(a,t.name).length>0&&<span className="tool-finding-count"><ListChecks size={12}/>{findingsForTool(a,t.name).length} {findingsForTool(a,t.name).length===1?"finding":"findings"}</span>}<span className="badge">{operationLabel(t.classification.operationType)}</span><StatusBadge value={t.risk}/></div></div></summary><div className="tool-detail-body">
    <div className="signal-grid"><Signal label="Primary area" value={plainTaxonomy(t.classification.domain)}/><Signal label="What it can do" value={t.classification.effects.map(plainTaxonomy).join(", ")||"No sensitive effect inferred"}/><Signal label="Data sensitivity" value={plainTaxonomy(t.classification.sensitivity)}/><Signal label="Potential reach" value={plainTaxonomy(t.classification.blastRadius)}/><Signal label="Classification evidence" value={`${confidenceLabel(t.confidence)} · ${Math.round(t.confidence*100)}%`}/><Signal label="Catalog visible to" value={t.visibleTo.join(", ")||"Unavailable"}/></div>
    <ToolFindings findings={findingsForTool(a,t.name)} onOpenFinding={onOpenFinding}/>
    <div className="tool-columns"><section><h3>Published contract</h3><ToolContractSummary tool={t}/></section><section><h3>Illustrative AgntID policy</h3><p>This preview is derived from catalog metadata. It was not enforced against GitHub.</p>{Object.values(t.policyPreview).map(p=><div className="policy-row" key={p.profile}><strong>{policyProfileLabel(p.profile)}</strong><StatusBadge value={p.disposition}/><small>{p.reasons.join(" · ")||"Available without an additional policy gate in this profile."}</small></div>)}</section></div>
    {t.classification.annotationContradictions.length>0&&<div className="notice danger-notice"><AlertTriangle size={15}/><span><strong>Annotation contradiction</strong><br/>{t.classification.annotationContradictions.join(" ")}</span></div>}
  </div></details>)}</div>}</Card><Card title="Estimated context budget"><div style={{padding:"10px 0 20px"}}><div style={{fontSize:34,fontWeight:750}}>{(a.context.totalTokens||0).toLocaleString()}</div><p className="subtitle">estimated tokens · {a.context.estimator||"pending"}</p><div className="progress" style={{marginTop:16,height:10}}><span style={{width:`${Math.min(100,a.context.utilization||0)}%`}}/></div><div className="field-help">{(a.context.utilization||0).toFixed(1)}% of {(a.context.contextWindow||128000).toLocaleString()} token context window</div></div>{[["Tools",a.context.toolTokens],["Prompts",a.context.promptTokens],["Resources",a.context.resourceTokens],["Instructions",a.context.instructionTokens]].map(([label,value])=><ProfileRow key={label} icon={<Gauge size={14}/>} label={String(label)} value={`${Number(value||0).toLocaleString()} tokens`}/>)}</Card></div>
  </div>}
function Metric({label,value,icon:Icon=Gauge,hint}:{label:string;value:number|string;icon?:LucideIcon;hint?:string}){return <div className="card metric compact-metric" title={hint}><span className="metric-icon"><Icon size={16}/></span><div><div className="metric-label">{label}{hint&&<InfoTip text={hint}/>}</div><div className="metric-value">{value}</div></div></div>}
function Signal({label,value}:{label:string;value:string}){return <div><span>{label}</span><strong>{value}</strong></div>}
function operationLabel(value:string){return ({READ:"Reads data",LIST:"Finds data",CREATE:"Creates data",WRITE:"Changes data",DELETE:"Deletes data",EXECUTE:"Runs an action",OTHER:"Action needs review"} as Record<string,string>)[value]||plainTaxonomy(value)}
function plainTaxonomy(value:string){return value.toLowerCase().replaceAll("_"," ")}
function policyProfileLabel(value:string){return ({"read-only":"Read only","read-write":"Read and write",protected:"Protected"} as Record<string,string>)[value]||plainTaxonomy(value)}
function ToolContractSummary({tool}:{tool:ToolProfile}){const noArguments=tool.schema.propertyCount===0;return <>
  <div className="contract-summary">
    <div><span>Input contract</span><strong>{noArguments?"No arguments declared":`${tool.schema.propertyCount} input ${tool.schema.propertyCount===1?"field":"fields"}`}</strong><small>{noArguments?"Description coverage: not applicable":`${Math.round(tool.schema.descriptionCoverage)}% of input fields described`}</small></div>
    <div><span>Output contract</span><strong>{tool.schema.hasOutputSchema?"Structured output declared":"Structured output not declared"}</strong><small>{tool.schema.hasOutputSchema?"Returned data can be checked against a declared shape":"Returned data cannot be validated against a declared shape"}</small></div>
  </div>
  {tool.schema.inputRisks.length>0&&<div className="input-boundaries"><h4>OWASP-aligned input boundaries</h4>{tool.schema.inputRisks.map(r=><div className="input-boundary" key={`${r.kind}-${r.path}`}><StatusBadge value={r.severity}/><span><strong>{r.kind.replaceAll("_"," ")} · {r.path}</strong><small>{r.reason}</small></span><span className={`badge ${r.constrained?"completed":"partial"}`}>{r.constrained?"declared constraint":"unconstrained"}</span></div>)}</div>}
  {tool.schema.signals.length?<div className="schema-observations"><h4>What this means</h4>{tool.schema.signals.map(signal=><SchemaObservation signal={signal} noArguments={noArguments} key={`${signal.code}-${signal.path}`}/>)}</div>:<div className="good-signal"><ShieldCheck size={14}/>No contract-quality observations.</div>}
  <p className="contract-boundary"><ShieldCheck size={13}/>These observations describe the published contract. They do not prove the tool is unsafe, that the current identity can execute it, or that its implementation will fail.</p>
</>}
function SchemaObservation({signal,noArguments}:{signal:SchemaSignal;noArguments:boolean}){const copy=schemaObservationCopy(signal,noArguments);return <div className="schema-observation"><StatusBadge value={signal.severity}/><div><strong>{copy.title}</strong><p>{copy.meaning}</p><details className="contract-evidence"><summary>Technical evidence</summary><code>{signal.code}{signal.path?` · ${signal.path}`:""}</code><p>{signal.message}</p></details></div></div>}
function schemaObservationCopy(signal:SchemaSignal,noArguments:boolean){switch(signal.code){case "schema.additional_properties_unspecified":return {title:noArguments?"Tool contract permits undeclared arguments":"Tool contract permits undeclared input fields",meaning:noArguments?"This MCP tool declares no named inputs, but its JSON Schema allows extra fields. If the tool truly accepts no arguments, the server author should set additionalProperties to false. This affects client-side validation, not user access or permissions; runtime handling was not tested.":"This MCP tool's JSON Schema allows fields that are not named in its input contract. The server author can reject them with additionalProperties set to false. This affects client-side validation, not user access or permissions; runtime handling was not tested."};case "schema.additional_properties_allowed":return {title:"Tool contract permits undeclared input fields",meaning:"The MCP input contract explicitly allows fields it does not name. This affects client-side validation and predictability, not user access or permissions."};case "schema.output_missing":return {title:"Returned data has no declared structure",meaning:"Agents cannot validate the result against a published shape. This reduces predictability, but does not mean the tool will fail or return unsafe data."};case "schema.description_coverage":return {title:"Some input fields lack descriptions",meaning:"Agents may need to infer how those fields should be used, increasing the chance of incorrect calls."};case "schema.unconstrained_string":return {title:"A text input has no declared constraints",meaning:"The contract does not bound the accepted text values or format, so runtime validation matters more."};default:return {title:"Contract detail needs review",meaning:signal.message}}}
function IntegrityDrift({a}:{a:Assessment}){return <div className="grid">
  <div className="grid metrics-grid"><Metric label="Metadata surfaces reviewed" value={a.contentIntegrity.itemsScanned} icon={ScanSearch}/><Metric label="Deterministic warning patterns" value={a.contentIntegrity.signals.length} icon={ShieldAlert}/><Metric label="Catalog comparison" value={a.catalogDrift.compared?a.catalogDrift.added+a.catalogDrift.removed+a.catalogDrift.modified:"Baseline only"} icon={Fingerprint}/><Metric label="Average contract quality" value={a.readiness.averageScore} icon={Gauge} hint="Average observable declaration quality across discovered tools."/></div>
  <div className="grid two-column"><Card title="Catalog drift" description="Changes since the previous catalog." action={<InfoTip text="Drift can come from deployments, dynamic configuration, SDK changes, or identity-specific visibility. Severity indicates review urgency, not malicious intent."/>}>
    <div className="drift-summary"><span><b>{a.catalogDrift.added}</b> added</span><span><b>{a.catalogDrift.removed}</b> removed</span><span><b>{a.catalogDrift.modified}</b> modified</span></div>
    {a.catalogDrift.changes.length===0?<div className="good-signal"><ShieldCheck size={14}/>{a.catalogDrift.compared?"No declaration changes detected since the prior assessment.":"Baseline recorded; the next assessment of this URL will show changes."}</div>:a.catalogDrift.changes.map(change=><details className="governance-item compact-disclosure" key={`${change.changeType}-${change.toolName}`}><summary><span className="item-icon"><Fingerprint size={15}/></span><div><h3>{change.toolName}</h3><p>{change.summary}</p></div><div><StatusBadge value={change.severity}/><span className="badge">{change.changeType}</span></div><ChevronDown size={14}/></summary><div className="disclosure-body"><small><strong>Changed fields:</strong> {change.fields.join(" · ")}</small><div className="notice"><Fingerprint size={14}/><span><strong>Review focus</strong><br/>{change.policyImpact}</span></div></div></details>)}
    <p className="field-help">{a.catalogDrift.disclaimer}</p>
  </Card><Card title="Metadata integrity" description="Instruction and secret-handling indicators." action={<InfoTip text="Metadata can influence tool choice before runtime policy evaluates a call. These are deterministic review leads, not a safety score or proof of execution."/>}>
    {a.contentIntegrity.signals.length===0?<div className="good-signal"><ShieldCheck size={14}/>No deterministic warning patterns were found across {a.contentIntegrity.itemsScanned} advertised metadata surfaces.</div>:a.contentIntegrity.signals.map(signal=><details className="governance-item compact-disclosure" key={signal.id}><summary><span className="item-icon danger"><ShieldAlert size={15}/></span><div><h3>{signal.title}</h3><p>{signal.surfaceKind} · <strong>{signal.surfaceId}</strong></p></div><StatusBadge value={signal.severity}/><ChevronDown size={14}/></summary><div className="disclosure-body">{signal.matchedText&&<blockquote>{signal.matchedText}</blockquote>}<small>{confidenceLabel(signal.confidence)} signature evidence · {Math.round(signal.confidence*100)}% · {signal.ruleId}</small><div className="notice danger-notice"><AlertTriangle size={14}/><span>{signal.recommendation}</span></div></div></details>)}
    <p className="field-help">{a.contentIntegrity.disclaimer}</p>
  </Card></div>
  <ContentInventory a={a}/>
  <Card title="Tool contract readiness" description="Start with the repeated contract gaps, then inspect individual tools only when needed." action={<InfoTip text="Score measures declaration quality from 0–100. Coverage is how much metadata could prove; lower coverage means uncertainty, not automatic failure."/>}><div className="readiness-scale"><span className="needs"><b>{a.readiness.tools.filter(tool=>tool.score<70).length}</b> Need work</span><span className="developing"><b>{a.readiness.tools.filter(tool=>tool.score>=70&&tool.score<85).length}</b> Developing</span><span className="strong"><b>{a.readiness.tools.filter(tool=>tool.score>=85).length}</b> Strong</span></div><ReadinessDrivers a={a}/>{a.readiness.tools.length===0?<div className="empty"><Gauge size={26}/>No tool contracts were available.</div>:<details className="all-tool-readiness"><summary>Review all {a.readiness.tools.length} tool scores <ChevronDown size={14}/></summary><div className="readiness-list">{a.readiness.tools.map(tool=><details className="tool-detail" key={tool.toolName}><summary><div className="tool-summary"><div><strong>{tool.toolName}</strong><span>{Math.round(tool.coverage)}% evidence coverage</span></div><div><strong className="readiness-score">{tool.score}</strong><div className="readiness-meter" aria-hidden="true"><span style={{width:`${tool.score}%`}}/></div><StatusBadge value={tool.score>=85?"strong":tool.score>=70?"developing":"needs-work"}/></div></div></summary><div className="tool-detail-body">{tool.checks.map(check=><div className="readiness-check" key={check.id}><StatusBadge value={check.status}/><div><strong>{check.title}</strong><p>{check.evidence}</p>{check.recommendation&&<small>{check.recommendation}</small>}</div></div>)}</div></details>)}</div></details>}</Card>
  <div className="conversion-card"><div><div className="eyebrow">Turn observation into control</div><h2>AgntID converts catalog change into a runtime decision.</h2></div><div className="conversion-flow"><span>Fingerprint</span><b>→</b><span>Review</span><b>→</b><span>Enforce</span><b>→</b><span>Audit</span></div></div>
</div>}
function ContentInventory({a}:{a:Assessment}){const counts=a.contentInventory.reduce((result,item)=>({...result,[item.kind]:(result[item.kind]||0)+1}),{} as Record<string,number>);return <Card title="Discovered agent-facing content" description="Instructions, prompts, and app resources can influence how an agent selects and uses tools."><div className="content-inventory-summary">{Object.entries(counts).map(([kind,count])=><span key={kind}><b>{count}</b>{plainTaxonomy(kind)}</span>)}</div><div className="content-inventory-list">{a.contentInventory.map(item=><details key={`${item.kind}-${item.id}`}><summary><span>{plainTaxonomy(item.kind)}</span><strong>{item.name||item.id}</strong><ChevronDown size={13}/></summary><p>{item.text||item.uri||"No descriptive text was advertised."}</p>{item.uri&&<code>{item.uri}</code>}</details>)}</div><p className="field-help">This inventory was inspected as metadata. Observatory did not render the MCP App resources or execute the advertised workflows.</p></Card>}
function ReadinessDrivers({a}:{a:Assessment}){const failures=new Map<string,{title:string;count:number}>();for(const tool of a.readiness.tools){for(const check of tool.checks){if(check.status!=="fail"&&check.status!=="not-observed")continue;const current=failures.get(check.id)||{title:check.title,count:0};current.count++;failures.set(check.id,current)}}const drivers=[...failures.values()].sort((left,right)=>right.count-left.count).slice(0,5);if(drivers.length===0)return null;return <div className="readiness-drivers"><strong>Most common gaps</strong>{drivers.map(driver=><div key={driver.title}><span>{driver.title}</span><b>{driver.count} tools</b></div>)}</div>}
function IdentityPolicy({a}:{a:Assessment}){const identities=a.identityExposure.profiles;const comparisonReady=a.identityExposure.comparedProfiles>=2;return <div className="grid">
  <div className="trust-strip"><Fingerprint size={16}/><strong>{a.identityExposure.comparedProfiles>0?"Catalog visibility measured":"No catalog visibility measured"}</strong><span>{comparisonReady?"Identity comparison available":"Add another connected identity to compare access"}</span><InfoTip text="Each credential receives an isolated MCP session. Observatory compares tools/list metadata only; visibility is not proof of authorization to execute."/></div>
  <OAuthSecurity a={a}/>
  {identities.length>0&&<Card title="Identity connection attempts" description="Each configured identity is tested in an isolated MCP session."><div className="identity-attempts">{identities.map(profile=><div className="identity-attempt" key={profile.id}><span className="identity-attempt-icon"><IdCard size={15}/></span><div><strong>{profile.label}</strong><small>{profile.authentication.replaceAll("-"," ")} · {profile.toolCount} tools visible</small>{profile.error&&<p>{profile.error}</p>}</div><StatusBadge value={profile.status}/></div>)}</div></Card>}
  <div className="grid metrics-grid"><Metric label="Connected identity profiles" value={a.identityExposure.comparedProfiles} icon={Users}/><Metric label="Anonymous tools advertised" value={a.identityExposure.anonymousToolCount} icon={Eye}/><Metric label="Measured access differences" value={comparisonReady?a.identityExposure.tools.filter(t=>t.hiddenFrom.length>0).length:"Not compared"} icon={LockKeyhole}/><Metric label="Potential capability chains" value={a.riskChains.length} icon={GitBranch}/></div>
  <Card title="Identity exposure matrix" description={comparisonReady?(a.identityExposure.privilegeSeparationObserved?"Connected identities received different advertised catalogs.":"Connected identities received equivalent advertised catalogs."):"Privilege separation cannot be evaluated until at least two authenticated identities connect."}>{identities.length===0?<div className="empty"><Users size={26}/>No identity catalog was available.</div>:<div className="table-wrap"><table><thead><tr><th>Tool</th>{identities.map(p=><th key={p.id}>{p.label}<br/><span className="muted-th">{p.status==="connected"?`${p.toolCount} tools`:"Not connected"}</span></th>)}</tr></thead><tbody>{a.identityExposure.tools.map(tool=><tr key={tool.toolName}><td><strong>{tool.toolName}</strong></td>{identities.map(p=><td key={p.id}><IdentityVisibility profile={p} visible={tool.visibleTo.includes(p.label)}/></td>)}</tr>)}</tbody></table></div>}<p className="field-help">Profile names such as “Reader” are labels supplied for the assessment. They do not prove the credential&apos;s actual GitHub permissions, and catalog visibility does not prove tool execution rights.</p></Card>
  <div className="grid two-column"><Card title="AgntID policy preview" description="Illustrative profiles show how runtime policy could reduce catalog exposure or pause higher-risk changes.">{a.policySimulation.profiles.map(p=><div className="policy-profile" key={p.id}><div><Sparkles size={15}/><strong>{p.name}</strong></div><div className="policy-counts"><span><b>{p.visibleCount}</b> visible</span><span><b>{p.hiddenCount}</b> hidden</span><span><b>{p.approvalCount}</b> approval</span></div>{p.id==="read-only"&&<small>{policyContextSummary(a,p.visibleToolNames)}</small>}</div>)}<p className="field-help">Metadata-derived preview only. These decisions were not deployed or enforced against the assessed server.</p></Card><Card title="Potential capability chains" description="These tools provide ingredients that could be combined; the sequence was not observed or executed.">{a.riskChains.length===0?<div className="empty"><GitBranch size={26}/>No deterministic capability chain matched.</div>:a.riskChains.map(chain=><div className="risk-chain" key={chain.id}><div><StatusBadge value={chain.severity}/><h3>{chain.title}</h3></div><p>{chain.description}</p><div>{chain.toolNames.slice(0,8).map(name=><span className="badge" key={name}>{name}</span>)}{chain.toolNames.length>8&&<span className="badge">+{chain.toolNames.length-8} more</span>}</div></div>)}</Card></div>
  <div className="conversion-card"><div><div className="eyebrow">From observation to enforcement</div><h2>Observatory shows the exposure. AgntID applies identity-aware policy at runtime.</h2><p>Use classified effects, schema signals, identity, risk, and approval requirements to hide tools, constrain access, and create an auditable decision trail.</p></div><div className="conversion-flow"><span>Discover</span><b>→</b><span>Classify</span><b>→</b><span>Decide</span><b>→</b><span>Audit</span></div></div>
</div>}
function IdentityVisibility({profile,visible}:{profile:Assessment["identityExposure"]["profiles"][number];visible:boolean}){if(profile.status!=="connected")return <span className="visibility no"><CircleDashed size={13}/>Unavailable</span>;return visible?<span className="visibility yes"><Eye size={13}/>Advertised</span>:<span className="visibility no"><EyeOff size={13}/>Not advertised</span>}
function policyContextSummary(a:Assessment,visibleToolNames:string[]){const reduced=estimatedProfileTokens(a,visibleToolNames);if(!a.context.totalTokens||!reduced)return "Context reduction could not be estimated.";const percentage=Math.round((1-reduced/a.context.totalTokens)*100);return `Estimated initialization context: ${a.context.totalTokens.toLocaleString()} → ${reduced.toLocaleString()} tokens (${percentage}% less).`}
function OAuthSecurity({a}:{a:Assessment}){const oauth=a.oauth;const controls=[{label:"Resource metadata",ok:oauth.resourceMetadataValid},{label:"Authorization metadata",ok:oauth.authorizationServerMetadataValid},{label:"PKCE S256",ok:oauth.pkceS256},{label:"DCR available",ok:oauth.dcrSupported},{label:"Scopes advertised",ok:oauth.scopes.length>0},{label:"Bearer header",ok:oauth.headerBearerSupported}];return <Card title="OAuth security posture" description={oauth.protected?"Discovery and authorization controls advertised by the protected MCP endpoint.":"The endpoint did not require OAuth for anonymous initialization."} action={<StatusBadge value={oauth.status}/>}>
  {oauth.protected?<><div className="oauth-control-grid">{controls.map(control=><div className={`oauth-control ${control.ok?"pass":"fail"}`} key={control.label}>{control.ok?<CheckCircle2 size={16}/>:<CircleX size={16}/>}<span>{control.label}</span></div>)}</div>
  <div className="oauth-summary"><div><IdCard size={15}/><span><small>New client setup</small><strong>{oauth.registrationMethod?`${oauth.registrationMethod} registration completed`:oauth.dcrSupported?"Dynamic registration advertised":"Pre-registered client required"}</strong></span></div><div><KeyRound size={15}/><span><small>Interactive OAuth flow</small><strong>{oauth.authorizedIdentities.join(", ")||"Not completed during this assessment"}</strong></span></div><div><ShieldCheck size={15}/><span><small>Advertised OAuth scopes</small><strong>{oauth.scopes.join(" · ")||"Not advertised"}</strong></span></div></div>
  {(oauth.issuer||oauth.diagnostics.length>0)&&<details className="oauth-details"><summary>View OAuth discovery evidence <ChevronDown size={13}/></summary><div>{oauth.issuer&&<ProfileRow icon={<Network size={14}/>} label="Issuer" value={oauth.issuer}/>} {oauth.resource&&<ProfileRow icon={<Fingerprint size={14}/>} label="Resource" value={oauth.resource}/>} {oauth.registrationEndpoint&&<ProfileRow icon={<IdCard size={14}/>} label="DCR endpoint" value={oauth.registrationEndpoint}/>} {oauth.diagnostics.map((item,index)=><div className="oauth-diagnostic" key={index}><AlertTriangle size={13}/>{item}</div>)}</div></details>}</>:<div className="notice danger-notice"><AlertTriangle size={15}/><span><strong>Anonymous access observed</strong><br/>Review the authentication finding and confirm whether public catalog discovery is intentional.</span></div>}
  <p className="field-help">OAuth checks validate advertised configuration and authorization completion. They do not prove token enforcement for individual tool calls.</p>
</Card>}
function Evidence({a}:{a:Assessment}){return <Card title={`${a.evidence.length} evidence records`} description="Evidence records are the technical audit trail. Start with what was observed; open the raw record only when verification is needed.">{a.evidence.map(e=><details className="evidence-record" key={e.id}><summary><StatusBadge value={e.observation.provenance}/><strong>{e.title}</strong><span>{confidenceLabel(e.observation.confidence)} · {Math.round(e.observation.confidence*100)}%</span></summary><p>{e.summary}</p><details className="technical-record"><summary>View technical record</summary><pre>{JSON.stringify(e.data,null,2)}</pre></details></details>)}</Card>}
function Timeline({a}:{a:Assessment}){return <Card title="Assessment timeline" description="Stages distinguish completed checks from areas that could not be assessed."><div className="timeline">{a.engineRuns.map(run=>{const status=timelineStatus(a,run.id,run.status);const message=status==="not-assessed"?"Tool execution authorization was not assessed; catalog visibility only":run.message||"Waiting to run";return <div className="timeline-item" key={run.id}><span className="timeline-dot"/><div style={{display:"flex",gap:10,alignItems:"center"}}><h3>{run.name}</h3><StatusBadge value={status}/></div><p>{message}{run.durationMs?` · ${run.durationMs} ms`:""}</p></div>})}</div></Card>}
function timelineStatus(a:Assessment,runId:string,status:string){if(runId==="authorization"&&a.facts?.["authorization.assessed"]!==true)return "not-assessed";return status}
function Artifacts({a}:{a:Assessment}){return <Card title="Generated artifacts" description="Machine-readable, executive, and technical formats share one canonical report model.">{a.artifacts.length===0?<div className="empty"><FileJson size={26}/>Artifacts will appear after report generation.</div>:<div className="table-wrap"><table><thead><tr><th>Artifact</th><th>Audience</th><th>Format</th><th>Size</th><th></th></tr></thead><tbody>{a.artifacts.map(item=><tr key={item.id}><td><strong>{item.name}</strong></td><td><StatusBadge value={item.kind}/></td><td>{item.format.toUpperCase()}</td><td>{Math.max(1,Math.round(item.size/1024))} KB</td><td style={{textAlign:"right"}}><a className="button" href={artifactURL(a.id,item.id)}><Download size={13}/>Download</a></td></tr>)}</tbody></table></div>}</Card>}
